1: import type { Vec3 } from '../contracts/math';
2: import { clamp } from '../physics/helpers';
3: import { addVec3, lengthVec3, rotateAroundY, scaleVec3, subVec3 } from './vec';
4: 
5: export interface BoxZone {
6:   shape: 'box';
7:   center: Vec3;
8:   halfExtents: Vec3;
9:   /** yaw in radians, 0 keeps the box axis aligned */
10:   rotationY?: number;
11: }
12: 
13: export interface SphereZone {
14:   shape: 'sphere';
15:   center: Vec3;
16:   radius: number;
17: }
18: 
19: export interface CylinderZone {
20:   shape: 'cylinder';
21:   center: Vec3;
22:   radius: number;
23:   halfHeight: number;
24: }
25: 
26: export type ZoneShape = BoxZone | SphereZone | CylinderZone;
27: 
28: /** World point expressed in zone local space, rotation removed for oriented boxes. */
29: export function toZoneLocal(zone: ZoneShape, point: Vec3): Vec3 {
30:   const offset = subVec3(point, zone.center);
31:   if (zone.shape === 'box' && zone.rotationY) return rotateAroundY(offset, -zone.rotationY);
32:   return offset;
33: }
34: 
35: export function zoneContains(zone: ZoneShape, point: Vec3, margin = 0): boolean {
36:   const local = toZoneLocal(zone, point);
37:   if (zone.shape === 'box') {
38:     return (
39:       Math.abs(local.x) <= zone.halfExtents.x + margin &&
40:       Math.abs(local.y) <= zone.halfExtents.y + margin &&
41:       Math.abs(local.z) <= zone.halfExtents.z + margin
42:     );
43:   }
44:   if (zone.shape === 'sphere') return lengthVec3(local) <= zone.radius + margin;
45:   return Math.hypot(local.x, local.z) <= zone.radius + margin && Math.abs(local.y) <= zone.halfHeight + margin;
46: }
47: 
48: /** 1 in the middle of the volume, 0 on its border, so a fan fades out towards the edge. */
49: export function zoneFalloff(zone: ZoneShape, point: Vec3): number {
50:   const local = toZoneLocal(zone, point);
51:   if (zone.shape === 'box') {
52:     const ratio = Math.max(
53:       axisRatio(local.x, zone.halfExtents.x),
54:       axisRatio(local.y, zone.halfExtents.y),
55:       axisRatio(local.z, zone.halfExtents.z),
56:     );
57:     return clamp(1 - ratio, 0, 1);
58:   }
59:   if (zone.shape === 'sphere') return clamp(1 - axisRatio(lengthVec3(local), zone.radius), 0, 1);
60:   const radial = axisRatio(Math.hypot(local.x, local.z), zone.radius);
61:   return clamp(1 - Math.max(radial, axisRatio(local.y, zone.halfHeight)), 0, 1);
62: }
63: 
64: /** Nearest point inside the volume, used to keep a teleporter exit clear of walls. */
65: export function clampToZone(zone: ZoneShape, point: Vec3): Vec3 {
66:   const local = clampLocal(zone, toZoneLocal(zone, point));
67:   const oriented = zone.shape === 'box' && zone.rotationY ? rotateAroundY(local, zone.rotationY) : local;
68:   return addVec3(zone.center, oriented);
69: }
70: 
71: function clampLocal(zone: ZoneShape, local: Vec3): Vec3 {
72:   if (zone.shape === 'box') {
73:     return {
74:       x: clamp(local.x, -zone.halfExtents.x, zone.halfExtents.x),
75:       y: clamp(local.y, -zone.halfExtents.y, zone.halfExtents.y),
76:       z: clamp(local.z, -zone.halfExtents.z, zone.halfExtents.z),
77:     };
78:   }
79:   if (zone.shape === 'sphere') {
80:     const length = lengthVec3(local);
81:     if (length <= zone.radius || length < 1e-8) return local;
82:     return scaleVec3(local, zone.radius / length);
83:   }
84:   const radial = Math.hypot(local.x, local.z);
85:   const scale = radial <= zone.radius || radial < 1e-8 ? 1 : zone.radius / radial;
86:   return { x: local.x * scale, y: clamp(local.y, -zone.halfHeight, zone.halfHeight), z: local.z * scale };
87: }
